import{_ as a,o as e,c as d,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const b=JSON.parse('{"title":"第 8 章 AI 团队：一句话召唤多智能体协作","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 8 章 AI 团队：一句话召唤多智能体协作.md"};function r(l,t,o,i,h,p){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-8-章-ai-团队-一句话召唤多智能体协作" tabindex="-1">第 8 章 AI 团队：一句话召唤多智能体协作 <a class="header-anchor" href="#第-8-章-ai-团队-一句话召唤多智能体协作" aria-label="Permalink to &quot;第 8 章 AI 团队：一句话召唤多智能体协作&quot;">​</a></h1><blockquote><p>本章目标：理解 AI 团队的价值与组建流程。学会判断&quot;什么时候值得开团队&quot;、看懂团队分工方案、走通&quot;建团→派活→汇报→验收&quot;全流程。<strong>AI 团队不是炫技，而是把复杂度拆成可并行、可验收的单元。</strong></p></blockquote><h2 id="_8-1-一个人的算力不够时" tabindex="-1">8.1 一个人的算力不够时 <a class="header-anchor" href="#_8-1-一个人的算力不够时" aria-label="Permalink to &quot;8.1 一个人的算力不够时&quot;">​</a></h2><p>当任务足够复杂——既要做产品设计、又要写代码、又要写测试、还要写文档——单打独斗就不划算了。这时，我可以<strong>组建一支 AI 团队</strong>：多个智能体各司其职，并行推进，我作为 Leader 负责协调和把关。</p><h3 id="_8-1-1-真实工作场景类比" tabindex="-1">8.1.1 真实工作场景类比 <a class="header-anchor" href="#_8-1-1-真实工作场景类比" aria-label="Permalink to &quot;8.1.1 真实工作场景类比&quot;">​</a></h3><p>想想现实中的项目组：一个项目经理（Leader）+ 开发 + 测试 + 文档。<strong>一个人干完所有事不是不可能，而是效率低、质量难保证</strong>。AI 团队就是把这种分工复制到 AI 世界。</p><h2 id="_8-2-什么时候值得开团队" tabindex="-1">8.2 什么时候值得开团队 <a class="header-anchor" href="#_8-2-什么时候值得开团队" aria-label="Permalink to &quot;8.2 什么时候值得开团队&quot;">​</a></h2><h3 id="_8-2-1-场景对比" tabindex="-1">8.2.1 场景对比 <a class="header-anchor" href="#_8-2-1-场景对比" aria-label="Permalink to &quot;8.2.1 场景对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>单打独斗</th><th>开团队</th></tr></thead><tbody><tr><td>大项目全流程（开发+测试+文档）</td><td>串行，慢</td><td>并行，快</td></tr><tr><td>需要多角色视角</td><td>一个视角</td><td>多角色互查</td></tr><tr><td>任务可明确拆解</td><td>一个人做到底</td><td>分派给专人</td></tr><tr><td>高风险交付</td><td>凭感觉</td><td>有专职 reviewer</td></tr></tbody></table><h3 id="_8-2-2-判断标准" tabindex="-1">8.2.2 判断标准 <a class="header-anchor" href="#_8-2-2-判断标准" aria-label="Permalink to &quot;8.2.2 判断标准&quot;">​</a></h3><blockquote><p><strong>任务能否清晰拆成几个相对独立的子任务？</strong></p><ul><li>能 → 值得开团队；</li><li>不能 → 先一个人干。</li></ul></blockquote><div class="tip custom-block"><p class="custom-block-title">判断辅助</p><p>拆开后的子任务<strong>相互依赖越小</strong>，团队效率越高。如果子任务之间强耦合、频繁互相等待，团队反而拖慢进度。</p></div><h2 id="_8-3-团队怎么组建" tabindex="-1">8.3 团队怎么组建 <a class="header-anchor" href="#_8-3-团队怎么组建" aria-label="Permalink to &quot;8.3 团队怎么组建&quot;">​</a></h2><h3 id="_8-3-1-完整流程" tabindex="-1">8.3.1 完整流程 <a class="header-anchor" href="#_8-3-1-完整流程" aria-label="Permalink to &quot;8.3.1 完整流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;帮我做个团队，把 X 项目从开发到测试到文档全包了&quot;</span></span>
<span class="line"><span>我（Leader）：</span></span>
<span class="line"><span>  1. 确认模型配置（有哪些可用模型/后端）</span></span>
<span class="line"><span>  2. 说明团队分工方案（角色表）</span></span>
<span class="line"><span>  3. 你确认后，创建团队</span></span>
<span class="line"><span>  4. 生成每个成员（如：开发、测试）</span></span>
<span class="line"><span>  5. 给每个成员下发初始任务</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">先确认再建团</p><p><strong>分工方案一定先给你确认，我不擅自开团。</strong> 就像现实中你不会让项目经理未经批准就招人。</p></div><h3 id="_8-3-2-一个典型团队配置" tabindex="-1">8.3.2 一个典型团队配置 <a class="header-anchor" href="#_8-3-2-一个典型团队配置" aria-label="Permalink to &quot;8.3.2 一个典型团队配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>职责</th><th>类比</th></tr></thead><tbody><tr><td><strong>Leader（我）</strong></td><td>拆任务、派活、验收、协调</td><td>项目经理</td></tr><tr><td><strong>开发</strong></td><td>实现功能</td><td>工程师</td></tr><tr><td><strong>测试</strong></td><td>写测试、跑测试、报告问题</td><td>QA</td></tr></tbody></table><h2 id="_8-4-团队协作的工作流" tabindex="-1">8.4 团队协作的工作流 <a class="header-anchor" href="#_8-4-团队协作的工作流" aria-label="Permalink to &quot;8.4 团队协作的工作流&quot;">​</a></h2><h3 id="_8-4-1-标准工作流" tabindex="-1">8.4.1 标准工作流 <a class="header-anchor" href="#_8-4-1-标准工作流" aria-label="Permalink to &quot;8.4.1 标准工作流&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader 拆解任务 → 分派给成员 → 成员执行并回报</span></span>
<span class="line"><span>→ Leader 汇总/互查 → 发现问题 → 打回修订 → 验收交付</span></span></code></pre></div><h3 id="_8-4-2-任务看板-让进度可见" tabindex="-1">8.4.2 任务看板：让进度可见 <a class="header-anchor" href="#_8-4-2-任务看板-让进度可见" aria-label="Permalink to &quot;8.4.2 任务看板：让进度可见&quot;">​</a></h3><p>我作为 Leader 会用任务看板管理进度：谁在做什么、谁被谁阻塞、哪些已完成——一目了然。</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td>pending</td><td>待开始</td><td>测试任务等开发完成</td></tr><tr><td>in_progress</td><td>进行中</td><td>开发正在实现登录功能</td></tr><tr><td>completed</td><td>已完成</td><td>文档已写完</td></tr><tr><td>deleted</td><td>已撤销</td><td>需求变更，该任务取消</td></tr></tbody></table><h3 id="_8-4-3-并行-vs-串行" tabindex="-1">8.4.3 并行 vs 串行 <a class="header-anchor" href="#_8-4-3-并行-vs-串行" aria-label="Permalink to &quot;8.4.3 并行 vs 串行&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发(登录模块) ──────────────┐</span></span>
<span class="line"><span>                             ├→ 联调 → 验收</span></span>
<span class="line"><span>开发(订单模块) ──────────────┤</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>文档(接口文档，可并行) ───────┘</span></span></code></pre></div><p><strong>能并行的绝不串行，这就是团队最大的价值。</strong></p><h2 id="_8-5-团队协作的纪律" tabindex="-1">8.5 团队协作的纪律 <a class="header-anchor" href="#_8-5-团队协作的纪律" aria-label="Permalink to &quot;8.5 团队协作的纪律&quot;">​</a></h2><ul><li><strong>先出方案再建团</strong>：分工表先给你确认，不擅自开团；</li><li><strong>任务要拆得清</strong>：子任务之间边界明确，减少互相等待；</li><li><strong>Leader 要验收</strong>：不是派完活就结束，而是要检查结果；</li><li><strong>不合适就撤</strong>：任务缩小了，可以关掉多余成员，不让团队空转。</li></ul><h3 id="_8-5-1-团队纪律的意义" tabindex="-1">8.5.1 团队纪律的意义 <a class="header-anchor" href="#_8-5-1-团队纪律的意义" aria-label="Permalink to &quot;8.5.1 团队纪律的意义&quot;">​</a></h3><p>纪律不是束缚，而是保证<strong>结果可预期、过程可回溯</strong>：</p><ul><li>边界清晰 → 成员不越权、不打架；</li><li>验收严格 → 交付质量有底线；</li><li>动态收缩 → 成本可控，不浪费算力。</li></ul><h2 id="_8-6-单人-vs-团队决策表" tabindex="-1">8.6 单人 vs 团队决策表 <a class="header-anchor" href="#_8-6-单人-vs-团队决策表" aria-label="Permalink to &quot;8.6 单人 vs 团队决策表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务特征</th><th>选择</th><th>理由</th></tr></thead><tbody><tr><td>小任务/探索性任务/需求未定</td><td>单人，先跑通</td><td>团队开销大于收益</td></tr><tr><td>大项目/多角色/可拆解/交付高风险</td><td>团队，并行干</td><td>并行 + 多角色互查</td></tr><tr><td>需求变了/任务缩小</td><td>收缩回单人</td><td>不让团队空转</td></tr></tbody></table><h3 id="_8-6-1-成本意识" tabindex="-1">8.6.1 成本意识 <a class="header-anchor" href="#_8-6-1-成本意识" aria-label="Permalink to &quot;8.6.1 成本意识&quot;">​</a></h3><p><strong>开团队有成本</strong>（协调开销、模型资源），不是免费午餐：</p><ul><li>小任务开团队 = 杀鸡用牛刀；</li><li>需求未定的探索任务开团队 = 团队做无用功；</li><li>正确姿势：<strong>先单人探索验证，再团队规模化执行。</strong></li></ul><h2 id="_8-7-团队-×-其他章节" tabindex="-1">8.7 团队 × 其他章节 <a class="header-anchor" href="#_8-7-团队-×-其他章节" aria-label="Permalink to &quot;8.7 团队 × 其他章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组合</th><th>用法</th><th>参考</th></tr></thead><tbody><tr><td>团队 + 计划</td><td>大计划拆成子任务分派</td><td>第 7 章</td></tr><tr><td>团队 + 任务卡</td><td>每个成员用任务卡接收需求</td><td>第 2 章、附录 A</td></tr><tr><td>团队 + Skill</td><td>成员执行时调用专业 Skill</td><td>第 5、17 章</td></tr><tr><td>团队 + 记忆</td><td>共享团队上下文与决策</td><td>第 6、20 章</td></tr></tbody></table><h2 id="_8-8-本章练习" tabindex="-1">8.8 本章练习 <a class="header-anchor" href="#_8-8-本章练习" aria-label="Permalink to &quot;8.8 本章练习&quot;">​</a></h2><ol><li>想一个你手头的大任务，试着向我描述&quot;我想开个团队做这件事&quot;。</li><li>观察我给出的团队分工方案：角色是否合理？任务是否可拆？</li><li>确认后，走一遍&quot;建团 → 派活 → 汇报 → 验收&quot;全流程。</li><li>任务结束后复盘：团队模式比单人快了多少？哪些环节最值得开团队？</li></ol><hr><blockquote><p>小结：AI 团队不是炫技，而是<strong>把复杂度拆成可并行、可验收的单元</strong>。关键三问：任务可拆吗？拆得清吗？收益大于成本吗？——三问都过，就开团。<strong>第 16 章会讲更多协作细节，第 18 章教你设计自己的多 Agent 系统。</strong></p></blockquote>`,43)])])}const u=a(n,[["render",r]]);export{b as __pageData,u as default};
